def transform(g):
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]
    bg = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))
    for color in {v for row in g for v in row} - {bg}:
        cells = [(i, j) for i in range(h) for j in range(w) if g[i][j] == color]
        top, bottom = min(i for i, j in cells), max(i for i, j in cells)
        left, right = min(j for i, j in cells), max(j for i, j in cells)
        if (all(g[top][j] == g[bottom][j] == color for j in range(left, right + 1))
                and all(g[i][left] == g[i][right] == color for i in range(top, bottom + 1))):
            fill = 2 if (bottom - top - 1) % 2 == 0 else 7
            for i in range(top + 1, bottom):
                for j in range(left + 1, right):
                    if g[i][j] == bg:
                        out[i][j] = fill
    return out
